#include "stdafx.h"#include "HcdDebug.h"#include "HcdDebugApp.h"#include "HcdDebugSimpleFrame.h"#include "HcdDebugDoc.h"#include <rsuPaths.h>#include <macros/AutoCloser.h>#include <HcdMemoryService.h>// KHcdDebugAppIMPLEMENT_DYNCREATE(KHcdDebugApp, CWinThread)KHcdDebugApp::KHcdDebugApp(): m_pDocManager( NULL ){}KHcdDebugApp::~KHcdDebugApp(){}BOOL KHcdDebugApp::InitInstance(){	// TODO:  perform and per-thread initialization here	return TRUE;}int KHcdDebugApp::ExitInstance(){	// TODO:  perform any per-thread cleanup here	return CWinThread::ExitInstance();}BEGIN_MESSAGE_MAP(KHcdDebugApp, CWinThread)END_MESSAGE_MAP()// KHcdDebugApp message handlersvoid KHcdDebugApp::Open( IHcdDrawable **ppCtrls, size_t c, LPCSTR pszTitle, SStepCalcParams *pParams ){  AFX_MANAGE_STATE(AfxGetStaticModuleState());  AFX_MODULE_THREAD_STATE* pState = AfxGetModuleThreadState();  CWinThread* pThread = pState->m_pCurrentWinThread;  if( !pState->m_pCurrentWinThread )    pState->m_pCurrentWinThread = this;  if( !m_pDocManager )  {    void *pmem = KMemoryServiceHCD::Instance().NewMem( sizeof(*m_pDocManager) );    if( !pmem )      return;    m_pDocManager = new (pmem) CDocManager;    if( !m_pDocManager )      return;    pmem = KMemoryServiceHCD::Instance().NewMem( sizeof(CMultiDocTemplate) );    if( !pmem )      return;    /*HINSTANCE ht = GetModuleHandle("HcdDebugH5xxDebug");    if( !ht )      return;    if( !m_hInstance )      m_hInstance = ht;*/    //ASSERT( m_hInstance==ht );    CMultiDocTemplate* pDocTemplate = new (pmem) CMultiDocTemplate( IDR_HCDDEBUG,                                                                    RUNTIME_CLASS(KHcdDebugDoc),                                                                    RUNTIME_CLASS(KHcdDebugSimpleFrame),                                                                    NULL);    m_pDocManager->AddDocTemplate(pDocTemplate);  }  POSITION pos = m_pDocManager->GetFirstDocTemplatePosition();  CDocument* pOpenDocument = NULL;  if( !pOpenDocument )  {    char Path[_MAX_PATH] = { 0 };    m_pDocManager->OnFileNew();    pos = m_pDocManager->GetFirstDocTemplatePosition();    while (pos != NULL )    {      CDocTemplate* pTemplate = (CDocTemplate*)m_pDocManager->GetNextDocTemplate(pos);      ASSERT_KINDOF(CDocTemplate, pTemplate);      POSITION pos1 = pTemplate->GetFirstDocPosition();      while( pos1 )      {        pOpenDocument = pTemplate->GetNextDoc( pos1 );        if( pOpenDocument && pOpenDocument->IsKindOf( RUNTIME_CLASS(KHcdDebugDoc)) )        {          KHcdDebugDoc* pDoc = (KHcdDebugDoc*)pOpenDocument;          if( pDoc->m_ppCtrls )            continue;          pDoc->m_ppCtrls = ppCtrls;          pDoc->m_cCtrls = c;          pDoc->m_pParams = pParams;          /*if( pszSelectName )            pDoc->m_szFirstSelect = pszSelectName;*/          pDoc->SetTitle( pszTitle );          pos = pOpenDocument->GetFirstViewPosition();          CView *pView = pOpenDocument->GetNextView( pos );          if( pView )          {            CFrameWnd *pFr = pView->GetParentFrame();            if( pFr )            {              pFr->SendMessageToDescendants( WM_USER, 0, 77, TRUE, TRUE);            }          }          pos = NULL;          break;        }        else          pOpenDocument = NULL;      }    }  }  /*if( pOpenDocument )  {    pos = pOpenDocument->GetFirstViewPosition();    CView *pView = pOpenDocument->GetNextView( pos );    if( pView )    {      CFrameWnd *pFr = pView->GetParentFrame();      if( pFr )      {        if( !pFr->IsWindowVisible() )          pFr->ShowWindow( SW_SHOW );        pFr->SetActiveWindow();      }    }  }*/}CFrameWnd* KHcdDebugApp::IsAnyOpen( /*SH_Module *pEntry*/ ){  if( !m_pDocManager )    return NULL;  POSITION pos = m_pDocManager->GetFirstDocTemplatePosition();  CDocument* pOpenDocument = NULL;  while( pos != NULL )  {    CDocTemplate* pTemplate = (CDocTemplate*)m_pDocManager->GetNextDocTemplate(pos);    ASSERT_KINDOF(CDocTemplate, pTemplate);    POSITION pos1 = pTemplate->GetFirstDocPosition();    if( pos1 )    {      pOpenDocument = pTemplate->GetNextDoc( pos1 );      if( pOpenDocument && pOpenDocument->IsKindOf( RUNTIME_CLASS(KHcdDebugDoc)) )      {        KHcdDebugDoc* pDoc = (KHcdDebugDoc*)pOpenDocument;        /*if( pEntry==pDoc->m_entryModule )          break;*/      }      pOpenDocument = NULL;    }  }  if( pOpenDocument )  {    pos = pOpenDocument->GetFirstViewPosition();    CView *pView = pOpenDocument->GetNextView( pos );    if( pView )    {      CFrameWnd *pFr = pView->GetParentFrame();      if( pFr )      {        return pFr;        /*if( !pFr->IsWindowVisible() )          pFr->ShowWindow( SW_SHOW );        pFr->SetActiveWindow();*/      }    }  }  return FALSE;}class KThreadSupport{  struct S  {    HANDLE hThread;    KHcdDebugApp *pApp;  }_array[20];public:  KThreadSupport()  {    ZeroMemory( _array, sizeof(_array) );  }  KHcdDebugApp *Get()  {    HANDLE cur = GetCurrentThread();    int i = 0;    for( i; i<_countof(_array); ++i )    {      if( !_array[i].hThread )        break;      if( cur==_array[i].hThread )        return _array[i].pApp;    }    ASS( i<_countof(_array) );    _array[i].hThread = cur;    _array[i].pApp = new KHcdDebugApp;    return _array[i].pApp;  }}static s_controller;bool ShowDebugWnd( IHcdDrawable **ppCtrls, size_t c, LPCSTR pszPrjName, SStepCalcParams *pParams ){  KHcdDebugApp *pApp = s_controller.Get();  if( !pApp )    return false;  HINSTANCE ht = GetModuleHandle("HcdDebug");  AFX_MANAGE_STATE(AfxGetStaticModuleState());  AFX_MODULE_THREAD_STATE* pState = AfxGetModuleThreadState();  CWinThread* pThread = pState->m_pCurrentWinThread;  if( !pState->m_pCurrentWinThread )    pState->m_pCurrentWinThread = pApp;  pApp->Open( ppCtrls, c,  pszPrjName, pParams );  return true;}